import { errorLogger } from './errorLog';
import { withRuntimeSettings } from '/server/runtimeSettings';
import type { AnalyticsContext } from '/server/amplitude';

/**
 * Server operation registry.
 *
 * All logic lives in plain async functions `(ctx, args) => result`.
 * Meteor methods and the REST router are two thin wrappers over the same
 * registry (see server/transport.ts), so a future RN/Expo client can talk
 * to the same API over HTTP without any server-side rewrite.
 */

export interface OpContext {
  /** Data owner. Every query is scoped by it. */
  userId: string;
  analytics?: AnalyticsContext;
}

export type Operation<A = any, R = any> = (ctx: OpContext, args: A) => Promise<R>;

const operations = new Map<string, Operation>();

export function defineOperation<A, R>(name: string, handler: Operation<A, R>): string {
  if (operations.has(name)) {
    throw new Error(`Operation "${name}" already defined`);
  }
  operations.set(name, async (ctx, args) => {
    try {
      return await withRuntimeSettings(() => handler(ctx, args as A));
    } catch (error) {
      // Runs before the transport converts `Error('NO_PROFILE')` into a
      // Meteor.Error, so `shouldRecord` must already treat such codes as
      // expected; only real failures reach the admin journal.
      if (!errorLogger.hasRecorded(error) && errorLogger.shouldRecord(error)) {
        await errorLogger.record({ operation: name, actorUserId: ctx.userId, error });
      }
      throw error;
    }
  });
  return name;
}

export function getOperation(name: string): Operation | undefined {
  return operations.get(name);
}

export function operationNames(): string[] {
  return [...operations.keys()];
